using Core.Network.FusionAdapter.Runner;
using Core.Network.FusionAdapter.Spawning;
using Core.Network.Abstractions.Types;
using Fusion;
class Accessor2 : INetworkRunnerAccessor { public NetworkRunner Runner {get;set;} public bool IsRunning=>Runner != null && Runner.IsRunning; }
class Program2 {
 static readonly NetworkPrefabKey Prefab = new(){Value="avatar"};
 static async Task<int> Main() {
  int failed=0; foreach(var (name,test) in new (string,Func<Task>)[]{("late cancellation returns object", Late), ("changed runner cleans origin", Changed), ("stopped origin reports cleanup failure", Stopped), ("cleanup error propagates", CleanupError), ("cleanup failure retains ownership and cause", RetainsOwnership), ("precancel prevents spawn", Precancel), ("active callback survives late cancellation", ActiveCallback), ("stale callback suppressed", StaleCallback), ("reentrant callback changes session", Reentrant), ("callback after completion suppressed", CallbackAfterCompletion), ("null spawn reports failure", NullSpawn), ("foreign object rejects cleanup", Foreign), ("missing authority reports cleanup failure", NoAuthority), ("despawn uses object's original runner", DespawnOwner), ("despawn rejects invalid and unsafe objects", DespawnInvalid), ("despawn independent of current session", DespawnNoCurrent)}) { try { await test(); Console.WriteLine("PASS "+name); } catch(Exception e) { failed++; Console.WriteLine("FAIL "+name+": "+e.Message); } } return failed==0?0:1;
 }
 static (NetworkRunner,Accessor2,CancellationTokenSource,Task<Core.Network.Abstractions.Entities.INetworkEntity>,NetworkObject) Setup() { var r=new NetworkRunner(); var a=new Accessor2{Runner=r}; var c=new CancellationTokenSource(); var p=new FusionSpawner(a).SpawnAsync(Prefab,cancellationToken:c.Token).AsTask(); return (r,a,c,p,new NetworkObject{Runner=r}); }
 static Task DespawnOwner() { var owner = new NetworkRunner(); var current = new NetworkRunner(); var obj = new NetworkObject { Runner = owner }; new FusionSpawner(new Accessor2 { Runner = current }).Despawn(NetworkEntityAdapter.Wrap(obj)); if (owner.Despawned != obj || current.Despawned != null) throw new Exception("object sent to current runner instead of owner"); return Task.CompletedTask; }
 static Task DespawnNoCurrent() { var owner=new NetworkRunner(); var obj=new NetworkObject{Runner=owner}; new FusionSpawner(new Accessor2()).Despawn(NetworkEntityAdapter.Wrap(obj)); if(owner.Despawned!=obj) throw new Exception("owner not used when current absent"); return Task.CompletedTask; }
 static Task DespawnInvalid() { foreach(var kind in new[]{"destroyed", "invalid", "missing runner", "stopped", "not registered", "no authority"}) { var owner=new NetworkRunner(); var obj=new NetworkObject{Runner=owner}; var entity=new NetworkEntityAdapter{Object=obj}; switch(kind) { case "destroyed": obj.Destroyed=true; break; case "invalid": obj.IsValid=false; break; case "missing runner": obj.Runner=null; break; case "stopped": owner.IsRunning=false; break; case "not registered": owner.ContainsObject=false; break; case "no authority": obj.HasStateAuthority=false; break; } var current=new NetworkRunner(); bool rejected=false; try { new FusionSpawner(new Accessor2{Runner=current}).Despawn(entity); } catch(ArgumentException) { rejected=true; } catch(InvalidOperationException) { rejected=true; } if(!rejected || owner.Despawned!=null || current.Despawned!=null) throw new Exception("unsafe object not rejected: "+kind); } return Task.CompletedTask; }
 static async Task Late() {var (r,a,c,p,o)=Setup(); c.Cancel(); r.Pending.SetResult(o); if(NetworkEntityAdapter.Unwrap(await p)!=o) throw new Exception("wrong object");}
 static async Task Changed() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); r.Pending.SetResult(o); try {await p; throw new Exception("returned stale object");} catch(OperationCanceledException) {} if(r.Despawned!=o) throw new Exception("origin did not despawn");}
 static async Task Stopped() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); r.IsRunning=false; r.Pending.SetResult(o); try {await p; throw new Exception("returned stale object");} catch(InvalidOperationException e) {if(!e.Message.Contains("cleanup")) throw;} }
 static async Task Precancel() { var r=new NetworkRunner(); var c=new CancellationTokenSource(); c.Cancel(); var p=new FusionSpawner(new Accessor2{Runner=r}).SpawnAsync(Prefab,cancellationToken:c.Token).AsTask(); try { await p; throw new Exception("not cancelled"); } catch(OperationCanceledException) {} if(r.SpawnCalls!=0) throw new Exception("spawn started"); }
 static async Task ActiveCallback() { var r=new NetworkRunner(); var c=new CancellationTokenSource(); int calls=0; var p=new FusionSpawner(new Accessor2{Runner=r}).SpawnAsync(Prefab,beforeSpawned:e=>calls++,cancellationToken:c.Token).AsTask(); c.Cancel(); var o=new NetworkObject{Runner=r}; r.Before(r,o); r.Pending.SetResult(o); await p; if(calls!=1) throw new Exception("callback not invoked"); }
 static async Task StaleCallback() { var r=new NetworkRunner(); var a=new Accessor2{Runner=r}; int calls=0; var p=new FusionSpawner(a).SpawnAsync(Prefab,beforeSpawned:e=>calls++).AsTask(); a.Runner=new NetworkRunner(); var o=new NetworkObject{Runner=r}; r.Before(r,o); r.Pending.SetResult(o); try {await p; throw new Exception("not cancelled");} catch(OperationCanceledException) {} if(calls!=0) throw new Exception("stale callback invoked"); }
 static async Task Reentrant() {var r=new NetworkRunner(); var a=new Accessor2{Runner=r}; int calls=0; var p=new FusionSpawner(a).SpawnAsync(Prefab,beforeSpawned:e=>{calls++; a.Runner=new NetworkRunner();}).AsTask(); var o=new NetworkObject{Runner=r}; r.Before(r,o); r.Pending.SetResult(o); try {await p; throw new Exception("returned stale object");} catch(OperationCanceledException) {} if(calls!=1 || r.Despawned!=o) throw new Exception("reentrant session change not cleaned");}
 static async Task CallbackAfterCompletion() {var r=new NetworkRunner(); var a=new Accessor2{Runner=r}; int calls=0; var p=new FusionSpawner(a).SpawnAsync(Prefab,beforeSpawned:e=>calls++).AsTask(); var o=new NetworkObject{Runner=r}; r.Pending.SetResult(o); await p; r.Before(r,o); if(calls!=0) throw new Exception("completed spawn invoked callback");}
 static async Task NullSpawn() {var (r,a,c,p,o)=Setup(); r.Pending.SetResult(null); try {await p; throw new Exception("accepted null");} catch(InvalidOperationException) {} }
 static async Task Foreign() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); o.Runner=a.Runner; r.Pending.SetResult(o); try {await p; throw new Exception("accepted foreign object");} catch(InvalidOperationException e) {if(!e.Message.Contains("cleanup")) throw;} }
 static async Task NoAuthority() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); o.HasStateAuthority=false; r.Pending.SetResult(o); try {await p; throw new Exception("accepted cleanup without authority");} catch(InvalidOperationException e) {if(!e.Message.Contains("cleanup")) throw;} }
 static async Task RetainsOwnership() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); var cause=new Exception("despawn failed"); r.DespawnError=cause; r.Pending.SetResult(o); try {await p; throw new Exception("returned stale object");} catch(Exception e) { var t=e.GetType(); if(t.Name!="FusionSpawnCleanupException" || t.GetProperty("Origin")?.GetValue(e)!=r || !ReferenceEquals(t.GetProperty("SpawnedObject")?.GetValue(e),o) || e.InnerException!=cause) throw new Exception("cleanup failure lost origin, object or cause", e); }}
 static async Task CleanupError() {var (r,a,c,p,o)=Setup(); a.Runner=new NetworkRunner(); r.DespawnError=new Exception("despawn failed"); r.Pending.SetResult(o); try {await p; throw new Exception("returned stale object");} catch(Exception e) {if(!e.ToString().Contains("despawn failed")) throw;} }
}